-- Monthly client work ownership and explicit material requests. Never grants
-- book access, creates accounting facts, or approves/exports a voucher.
CREATE TABLE service_plan_versions(
 book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>0),
 lead_user_id TEXT REFERENCES users(id),reviewer_user_id TEXT REFERENCES users(id),backup_user_id TEXT REFERENCES users(id),contact_user_id TEXT REFERENCES users(id),
 due_on TEXT NOT NULL,notes TEXT NOT NULL CHECK(length(notes)<=2000),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL,
 PRIMARY KEY(book_id,version),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),CHECK(lead_user_id IS NULL OR reviewer_user_id IS NULL OR lead_user_id<>reviewer_user_id)
);
CREATE TABLE material_templates(
 id TEXT PRIMARY KEY,book_id TEXT NOT NULL,ledger_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version=1),
 name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),items_json TEXT NOT NULL,reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 UNIQUE(id,firm_id,company_id),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),FOREIGN KEY(ledger_id,firm_id,company_id) REFERENCES ledgers(id,firm_id,company_id)
);
CREATE TABLE material_requests(
 id TEXT PRIMARY KEY,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,period TEXT NOT NULL,template_id TEXT NOT NULL,item_key TEXT NOT NULL,
 title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120),description TEXT NOT NULL CHECK(length(description)<=1000),required INTEGER NOT NULL CHECK(required IN(0,1)),due_on TEXT NOT NULL,
 assignee_user_id TEXT REFERENCES users(id),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 UNIQUE(book_id,template_id,item_key),UNIQUE(id,book_id,firm_id,company_id),FOREIGN KEY(book_id,firm_id,company_id) REFERENCES books(id,firm_id,company_id),FOREIGN KEY(template_id,firm_id,company_id) REFERENCES material_templates(id,firm_id,company_id)
);
CREATE TABLE material_request_actions(
 id TEXT PRIMARY KEY,request_id TEXT NOT NULL,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>1),
 action TEXT NOT NULL CHECK(action IN('submit','accept','return')),state TEXT NOT NULL CHECK(state IN('submitted','accepted','returned')),mode TEXT CHECK(mode IN('provided','no_activity','not_applicable')),
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 3 AND 1000),event_ids_json TEXT NOT NULL,evidence_json TEXT NOT NULL,attachment_ids_json TEXT NOT NULL DEFAULT '[]',attachment_evidence_json TEXT NOT NULL DEFAULT '[]',created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 UNIQUE(request_id,version),FOREIGN KEY(request_id,book_id,firm_id,company_id) REFERENCES material_requests(id,book_id,firm_id,company_id),
 CHECK((action='submit' AND state='submitted' AND mode IS NOT NULL) OR (action='accept' AND state='accepted' AND mode IS NULL) OR (action='return' AND state='returned' AND mode IS NULL))
);
CREATE INDEX idx_service_plans_company ON service_plan_versions(firm_id,company_id,book_id,version DESC);
CREATE INDEX idx_material_templates_ledger ON material_templates(ledger_id,created_at,id);
CREATE INDEX idx_material_requests_assignee ON material_requests(firm_id,assignee_user_id,period,due_on,id);
CREATE INDEX idx_material_requests_book ON material_requests(book_id,due_on,id);

CREATE TABLE material_attachments(
 id TEXT PRIMARY KEY,request_id TEXT NOT NULL,book_id TEXT NOT NULL,firm_id TEXT NOT NULL,company_id TEXT NOT NULL,
 storage_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL CHECK(length(trim(filename)) BETWEEN 1 AND 150),media_type TEXT NOT NULL CHECK(media_type IN('application/pdf','image/png','image/jpeg','image/webp','application/xml','text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')),
 sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^a-f0-9]*'),size_bytes INTEGER NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,
 FOREIGN KEY(request_id,book_id,firm_id,company_id) REFERENCES material_requests(id,book_id,firm_id,company_id)
);
CREATE INDEX idx_material_attachments_request ON material_attachments(request_id,created_at,id);

CREATE TRIGGER material_attachment_guard BEFORE INSERT ON material_attachments BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM material_requests r JOIN company_memberships cm ON cm.company_id=r.company_id AND cm.user_id=r.assignee_user_id JOIN users u ON u.id=cm.user_id AND u.active=1 JOIN periods p ON p.book_id=r.book_id AND p.period=r.period AND p.status='open' JOIN companies c ON c.id=r.company_id AND c.status='active' JOIN firm_clients fc ON fc.firm_id=r.firm_id AND fc.company_id=r.company_id AND fc.status='active' WHERE r.id=NEW.request_id AND r.book_id=NEW.book_id AND r.firm_id=NEW.firm_id AND r.company_id=NEW.company_id AND r.assignee_user_id=NEW.created_by) THEN RAISE(ABORT,'Current assigned company member and open material request required') END;
 SELECT CASE WHEN coalesce((SELECT state FROM material_request_actions WHERE request_id=NEW.request_id ORDER BY version DESC LIMIT 1),'pending') NOT IN('pending','returned') OR (SELECT count(*) FROM material_attachments WHERE request_id=NEW.request_id)>=10 OR (SELECT coalesce(sum(size_bytes),0) FROM material_attachments WHERE request_id=NEW.request_id)+NEW.size_bytes>52428800 THEN RAISE(ABORT,'Editable request with bounded original attachments required') END;
END;
CREATE TRIGGER material_attachment_no_update BEFORE UPDATE ON material_attachments BEGIN SELECT RAISE(ABORT,'Original material attachments are immutable');END;
CREATE TRIGGER material_attachment_no_delete BEFORE DELETE ON material_attachments BEGIN SELECT RAISE(ABORT,'Original material attachments are immutable');END;
CREATE TRIGGER service_material_attachment_audit AFTER INSERT ON material_attachments BEGIN
 INSERT INTO audit_events(firm_id,book_id,company_id,user_id,action,object_id,details,created_at)
 VALUES(NEW.firm_id,NEW.book_id,NEW.company_id,NEW.created_by,'material.attachment.upload',NEW.request_id,json_object('attachment_id',NEW.id,'sha256',NEW.sha256,'size_bytes',NEW.size_bytes),NEW.created_at);
END;

CREATE VIEW service_book_user_permissions AS
 SELECT b.id AS book_id,u.id AS user_id,
 (m.role IN('owner','admin') OR ba.role IN('editor','reviewer') AND (m.role IN('operator','reviewer') OR m.role IS NULL AND cm.role IN('owner','admin','finance'))) AS can_edit,
 (m.role IN('owner','admin') OR ba.role='reviewer' AND (m.role='reviewer' OR m.role IS NULL AND cm.role='finance')) AS can_review,
 (cm.user_id IS NOT NULL) AS can_contact
 FROM books b JOIN companies c ON c.id=b.company_id AND c.status='active'
 JOIN firm_clients fc ON fc.firm_id=b.firm_id AND fc.company_id=b.company_id AND fc.status='active'
 JOIN users u ON u.active=1 LEFT JOIN memberships m ON m.firm_id=b.firm_id AND m.user_id=u.id
 LEFT JOIN company_memberships cm ON cm.company_id=b.company_id AND cm.user_id=u.id
 LEFT JOIN book_access ba ON ba.book_id=b.id AND ba.firm_id=b.firm_id AND ba.user_id=u.id;

CREATE TRIGGER service_plan_assignments BEFORE INSERT ON service_plan_versions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.updated_by AND p.can_edit) OR NEW.lead_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.lead_user_id AND p.can_edit) OR NEW.backup_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.backup_user_id AND p.can_edit) OR NEW.reviewer_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.reviewer_user_id AND p.can_review) OR NEW.contact_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.contact_user_id AND p.can_contact) THEN RAISE(ABORT,'Assignments require existing current permissions') END;
END;
CREATE TRIGGER material_template_permission BEFORE INSERT ON material_templates BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.created_by AND p.can_edit) THEN RAISE(ABORT,'Book editor required') END;
END;
CREATE TRIGGER material_request_permission BEFORE INSERT ON material_requests BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.created_by AND p.can_edit) THEN RAISE(ABORT,'Book editor required') END;
END;

CREATE TRIGGER service_plan_guard BEFORE INSERT ON service_plan_versions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM books b JOIN periods p ON p.book_id=b.id AND p.period=b.period JOIN companies c ON c.id=b.company_id AND c.status='active' JOIN firm_clients fc ON fc.firm_id=b.firm_id AND fc.company_id=b.company_id AND fc.status='active' WHERE b.id=NEW.book_id AND b.firm_id=NEW.firm_id AND b.company_id=NEW.company_id AND p.status='open') THEN RAISE(ABORT,'Current active same-company open period required') END;
 SELECT CASE WHEN NEW.version<>(SELECT coalesce(max(version),0)+1 FROM service_plan_versions WHERE book_id=NEW.book_id) OR date(NEW.due_on) IS NULL OR date(NEW.due_on)<>NEW.due_on THEN RAISE(ABORT,'Consecutive plan version and valid date required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(json_array(NEW.lead_user_id,NEW.reviewer_user_id,NEW.backup_user_id,NEW.contact_user_id)) wanted WHERE wanted.value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM users u WHERE u.id=wanted.value AND u.active=1)) THEN RAISE(ABORT,'Active assignees required') END;
END;
CREATE TRIGGER material_template_guard BEFORE INSERT ON material_templates BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM books b JOIN periods p ON p.book_id=b.id AND p.period=b.period JOIN ledger_periods lp ON lp.book_id=b.id JOIN companies c ON c.id=b.company_id AND c.status='active' JOIN firm_clients fc ON fc.firm_id=b.firm_id AND fc.company_id=b.company_id AND fc.status='active' WHERE b.id=NEW.book_id AND b.firm_id=NEW.firm_id AND b.company_id=NEW.company_id AND lp.ledger_id=NEW.ledger_id AND p.status='open') THEN RAISE(ABORT,'Same-ledger open period required') END;
 SELECT CASE WHEN json_valid(NEW.items_json)=0 OR json_type(NEW.items_json)<>'array' OR json_array_length(NEW.items_json) NOT BETWEEN 1 AND 30 OR (SELECT count(*)<>count(DISTINCT json_extract(value,'$.key')) FROM json_each(NEW.items_json)) THEN RAISE(ABORT,'Unique template items required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.items_json) item WHERE json_type(item.value,'$.key') IS NOT 'text' OR length(json_extract(item.value,'$.key')) NOT BETWEEN 1 AND 60 OR json_type(item.value,'$.title') IS NOT 'text' OR length(trim(json_extract(item.value,'$.title'))) NOT BETWEEN 1 AND 120 OR json_type(item.value,'$.required') NOT IN('true','false') OR json_type(item.value,'$.due_month_offset') IS NOT 'integer' OR json_extract(item.value,'$.due_month_offset') NOT IN(0,1) OR json_type(item.value,'$.due_day') IS NOT 'integer' OR json_extract(item.value,'$.due_day') NOT BETWEEN 1 AND 28 OR json_type(item.value,'$.assignee_user_id') IS NULL OR (json_extract(item.value,'$.assignee_user_id') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM company_memberships cm JOIN users u ON u.id=cm.user_id AND u.active=1 WHERE cm.company_id=NEW.company_id AND cm.user_id=json_extract(item.value,'$.assignee_user_id')))) THEN RAISE(ABORT,'Valid template item and current company assignee required') END;
END;
CREATE TRIGGER material_request_guard BEFORE INSERT ON material_requests BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM books b JOIN periods p ON p.book_id=b.id AND p.period=b.period JOIN ledger_periods lp ON lp.book_id=b.id JOIN material_templates t ON t.id=NEW.template_id AND t.ledger_id=lp.ledger_id AND t.firm_id=b.firm_id AND t.company_id=b.company_id JOIN json_each(t.items_json) item JOIN companies c ON c.id=b.company_id AND c.status='active' JOIN firm_clients fc ON fc.firm_id=b.firm_id AND fc.company_id=b.company_id AND fc.status='active' WHERE b.id=NEW.book_id AND b.firm_id=NEW.firm_id AND b.company_id=NEW.company_id AND b.period=NEW.period AND p.status='open' AND json_extract(item.value,'$.key')=NEW.item_key AND json_extract(item.value,'$.title')=NEW.title AND json_extract(item.value,'$.description')=NEW.description AND json_extract(item.value,'$.required')=NEW.required AND NEW.due_on=strftime('%Y-%m',b.period||'-01','+'||json_extract(item.value,'$.due_month_offset')||' months')||'-'||printf('%02d',json_extract(item.value,'$.due_day')) AND coalesce(json_extract(item.value,'$.assignee_user_id'),(SELECT contact_user_id FROM service_plan_versions WHERE book_id=NEW.book_id ORDER BY version DESC LIMIT 1))=NEW.assignee_user_id) THEN RAISE(ABORT,'Explicit same-ledger monthly template required') END;
 SELECT CASE WHEN NEW.assignee_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM company_memberships cm JOIN users u ON u.id=cm.user_id AND u.active=1 WHERE cm.company_id=NEW.company_id AND cm.user_id=NEW.assignee_user_id) THEN RAISE(ABORT,'Current company assignee required') END;
END;
CREATE TRIGGER material_action_guard BEFORE INSERT ON material_request_actions BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM material_requests r JOIN periods p ON p.book_id=r.book_id AND p.period=r.period JOIN companies c ON c.id=r.company_id AND c.status='active' JOIN firm_clients fc ON fc.firm_id=r.firm_id AND fc.company_id=r.company_id AND fc.status='active' WHERE r.id=NEW.request_id AND r.book_id=NEW.book_id AND r.firm_id=NEW.firm_id AND r.company_id=NEW.company_id AND p.status='open') THEN RAISE(ABORT,'Active same-company open request required') END;
 SELECT CASE WHEN NEW.version<>(SELECT coalesce(max(version),1)+1 FROM material_request_actions WHERE request_id=NEW.request_id) THEN RAISE(ABORT,'Consecutive material action version required') END;
 SELECT CASE WHEN NEW.action='submit' AND (coalesce((SELECT state FROM material_request_actions WHERE request_id=NEW.request_id ORDER BY version DESC LIMIT 1),'pending') NOT IN('pending','returned') OR NOT EXISTS(SELECT 1 FROM material_requests r JOIN company_memberships cm ON cm.company_id=r.company_id AND cm.user_id=r.assignee_user_id JOIN users u ON u.id=cm.user_id AND u.active=1 WHERE r.id=NEW.request_id AND r.assignee_user_id=NEW.created_by)) THEN RAISE(ABORT,'Only current assignee submits pending or returned material') END;
 SELECT CASE WHEN json_valid(NEW.event_ids_json)=0 OR json_type(NEW.event_ids_json)<>'array' OR json_array_length(NEW.event_ids_json)>30 OR json_valid(NEW.evidence_json)=0 OR json_type(NEW.evidence_json)<>'array' THEN RAISE(ABORT,'Bounded material evidence required') END;
 SELECT CASE WHEN NEW.action='submit' AND ((NEW.mode='provided')<>(json_array_length(NEW.event_ids_json)+json_array_length(NEW.attachment_ids_json)>0) OR (SELECT count(*)<>count(DISTINCT value) FROM json_each(NEW.event_ids_json)) OR json_array_length(NEW.evidence_json)<>json_array_length(NEW.event_ids_json) OR EXISTS(SELECT 1 FROM json_each(NEW.event_ids_json) refs JOIN material_requests r ON r.id=NEW.request_id WHERE NOT EXISTS(SELECT 1 FROM business_events e WHERE e.id=refs.value AND e.company_id=r.company_id AND e.firm_id=r.firm_id AND e.applicant_id=r.assignee_user_id AND substr(json_extract(e.payload,'$.occurred_on'),1,7)=r.period AND e.status<>'draft' AND EXISTS(SELECT 1 FROM business_attachments a WHERE a.event_id=e.id)))) THEN RAISE(ABORT,'Own same-month attached evidence required') END;
 SELECT CASE WHEN NEW.action<>'submit' AND (coalesce((SELECT state FROM material_request_actions WHERE request_id=NEW.request_id ORDER BY version DESC LIMIT 1),'pending') NOT IN('submitted','accepted') OR ((SELECT state FROM material_request_actions WHERE request_id=NEW.request_id ORDER BY version DESC LIMIT 1)='accepted' AND NEW.action<>'return') OR (SELECT created_by FROM material_request_actions WHERE request_id=NEW.request_id AND action='submit' ORDER BY version DESC LIMIT 1)=NEW.created_by OR NEW.event_ids_json<>'[]' OR NEW.evidence_json<>'[]' OR NEW.attachment_ids_json<>'[]' OR NEW.attachment_evidence_json<>'[]') THEN RAISE(ABORT,'Independent review cannot replace submitted evidence') END;
 SELECT CASE WHEN NEW.action<>'submit' AND NOT EXISTS(SELECT 1 FROM service_book_user_permissions p WHERE p.book_id=NEW.book_id AND p.user_id=NEW.created_by AND p.can_review) THEN RAISE(ABORT,'Current scoped book reviewer required') END;
 SELECT CASE WHEN NEW.action='submit' AND EXISTS(SELECT 1 FROM json_each(NEW.evidence_json) stamp WHERE json_extract(stamp.value,'$.event_id') IS NOT json_extract(NEW.event_ids_json,'$['||stamp.key||']') OR NOT EXISTS(SELECT 1 FROM business_events e WHERE e.id=json_extract(stamp.value,'$.event_id') AND coalesce(e.submitted_version,e.version)=json_extract(stamp.value,'$.event_version') AND e.fact_version=json_extract(stamp.value,'$.fact_version')) OR json_type(stamp.value,'$.attachments') IS NOT 'array' OR json_array_length(stamp.value,'$.attachments')<>(SELECT count(*) FROM business_attachments a WHERE a.event_id=json_extract(stamp.value,'$.event_id') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id)) OR EXISTS(SELECT 1 FROM json_each(stamp.value,'$.attachments') entry WHERE NOT EXISTS(SELECT 1 FROM business_attachments a WHERE a.id=json_extract(entry.value,'$.id') AND a.event_id=json_extract(stamp.value,'$.event_id') AND a.sha256=json_extract(entry.value,'$.sha256')))) THEN RAISE(ABORT,'Original evidence snapshot must match current facts') END;
 SELECT CASE WHEN NEW.action='accept' AND EXISTS(SELECT 1 FROM json_each((SELECT evidence_json FROM material_request_actions WHERE request_id=NEW.request_id ORDER BY version DESC LIMIT 1)) stamp WHERE NOT EXISTS(SELECT 1 FROM business_events e JOIN material_requests r ON r.id=NEW.request_id WHERE e.id=json_extract(stamp.value,'$.event_id') AND coalesce(e.submitted_version,e.version)=json_extract(stamp.value,'$.event_version') AND e.fact_version=json_extract(stamp.value,'$.fact_version') AND e.company_id=r.company_id AND e.applicant_id=r.assignee_user_id AND substr(json_extract(e.payload,'$.occurred_on'),1,7)=r.period) OR json_array_length(stamp.value,'$.attachments')<>(SELECT count(*) FROM business_attachments a WHERE a.event_id=json_extract(stamp.value,'$.event_id') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id)) OR EXISTS(SELECT 1 FROM json_each(stamp.value,'$.attachments') entry WHERE NOT EXISTS(SELECT 1 FROM business_attachments a WHERE a.id=json_extract(entry.value,'$.id') AND a.event_id=json_extract(stamp.value,'$.event_id') AND a.sha256=json_extract(entry.value,'$.sha256')))) THEN RAISE(ABORT,'Evidence changed; re-submit required') END;
END;

CREATE TRIGGER material_action_files BEFORE INSERT ON material_request_actions BEGIN
 SELECT CASE WHEN json_valid(NEW.attachment_ids_json)=0 OR json_type(NEW.attachment_ids_json)<>'array' OR json_array_length(NEW.attachment_ids_json)>30 OR json_valid(NEW.attachment_evidence_json)=0 OR json_type(NEW.attachment_evidence_json)<>'array' OR json_array_length(NEW.attachment_ids_json)<>json_array_length(NEW.attachment_evidence_json) OR (SELECT count(*)<>count(DISTINCT value) FROM json_each(NEW.attachment_ids_json)) THEN RAISE(ABORT,'Bounded unique attachment references required') END;
 SELECT CASE WHEN NEW.action='submit' AND EXISTS(SELECT 1 FROM json_each(NEW.attachment_evidence_json) stamp WHERE json_extract(stamp.value,'$.id') IS NOT json_extract(NEW.attachment_ids_json,'$['||stamp.key||']') OR NOT EXISTS(SELECT 1 FROM material_attachments a WHERE a.id=json_extract(stamp.value,'$.id') AND a.request_id=NEW.request_id AND a.sha256=json_extract(stamp.value,'$.sha256') AND a.created_by=NEW.created_by)) THEN RAISE(ABORT,'Current own original attachment hashes required') END;
 SELECT CASE WHEN NEW.action='accept' AND EXISTS(SELECT 1 FROM json_each((SELECT attachment_evidence_json FROM material_request_actions WHERE request_id=NEW.request_id AND action='submit' ORDER BY version DESC LIMIT 1)) stamp WHERE NOT EXISTS(SELECT 1 FROM material_attachments a WHERE a.id=json_extract(stamp.value,'$.id') AND a.request_id=NEW.request_id AND a.sha256=json_extract(stamp.value,'$.sha256'))) THEN RAISE(ABORT,'Original attachment evidence changed') END;
END;

CREATE TRIGGER service_plan_no_update BEFORE UPDATE ON service_plan_versions BEGIN SELECT RAISE(ABORT,'Service history is immutable');END;
CREATE TRIGGER service_plan_no_delete BEFORE DELETE ON service_plan_versions BEGIN SELECT RAISE(ABORT,'Service history is immutable');END;
CREATE TRIGGER material_template_no_update BEFORE UPDATE ON material_templates BEGIN SELECT RAISE(ABORT,'Material template history is immutable');END;
CREATE TRIGGER material_template_no_delete BEFORE DELETE ON material_templates BEGIN SELECT RAISE(ABORT,'Material template history is immutable');END;
CREATE TRIGGER material_request_no_update BEFORE UPDATE ON material_requests BEGIN SELECT RAISE(ABORT,'Material request history is immutable');END;
CREATE TRIGGER material_request_no_delete BEFORE DELETE ON material_requests BEGIN SELECT RAISE(ABORT,'Material request history is immutable');END;
CREATE TRIGGER material_action_no_update BEFORE UPDATE ON material_request_actions BEGIN SELECT RAISE(ABORT,'Material action history is immutable');END;
CREATE TRIGGER material_action_no_delete BEFORE DELETE ON material_request_actions BEGIN SELECT RAISE(ABORT,'Material action history is immutable');END;

CREATE TRIGGER service_material_audit AFTER INSERT ON material_request_actions BEGIN
 INSERT INTO audit_events(firm_id,book_id,company_id,user_id,action,object_id,details,created_at)
 VALUES(NEW.firm_id,NEW.book_id,NEW.company_id,NEW.created_by,'material.'||NEW.action,NEW.request_id,json_object('reason',NEW.reason,'version',NEW.version,'mode',NEW.mode),NEW.created_at);
END;





CREATE VIEW closing_fact_basis_stage24 AS SELECT b.id AS book_id,json_patch(v.inputs_json,json_object('monthly_baselines',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'book_id',t.book_id,'ledger_id',t.ledger_id,'firm_id',t.firm_id,'company_id',t.company_id,'kind',t.kind,'version',t.version,'period',t.period,'external_reference',t.external_reference,'evidence_ref',t.evidence_ref,'reason',t.reason,'original_format',t.original_format,'original_filename',t.original_filename,'original_content',t.original_content,'source_kind',t.source_kind,'source_id',t.source_id,'lines_json',t.lines_json,'created_by',t.created_by,'created_at',t.created_at,'request_key',t.request_key,'request_fingerprint',t.request_fingerprint) AS record FROM monthly_baselines t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.ledger_id))),'monthly_baseline_confirmations',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('baseline_id',t.baseline_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'confirmed_by',t.confirmed_by,'reason',t.reason,'created_at',t.created_at) AS record FROM monthly_baseline_confirmations t WHERE t.book_id=b.id ORDER BY t.baseline_id,t.book_id,t.firm_id))),'monthly_checks',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'book_id',t.book_id,'ledger_id',t.ledger_id,'firm_id',t.firm_id,'company_id',t.company_id,'version',t.version,'opening_id',t.opening_id,'closing_id',t.closing_id,'inputs_json',t.inputs_json,'report_json',t.report_json,'input_fingerprint',t.input_fingerprint,'created_by',t.created_by,'created_at',t.created_at,'request_key',t.request_key,'request_fingerprint',t.request_fingerprint) AS record FROM monthly_checks t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.ledger_id))),'monthly_check_closures',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('check_id',t.check_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'closed_by',t.closed_by,'reason',t.reason,'created_at',t.created_at) AS record FROM monthly_check_closures t WHERE t.book_id=b.id ORDER BY t.check_id,t.book_id,t.firm_id))),'recurring_plan_versions',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('plan_id',t.plan_id,'version',t.version,'ledger_id',t.ledger_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'name',t.name,'start_period',t.start_period,'end_period',t.end_period,'day',t.day,'description',t.description,'evidence_ref',t.evidence_ref,'reason',t.reason,'lines_json',t.lines_json,'catalog_json',t.catalog_json,'created_by',t.created_by,'created_at',t.created_at,'request_key',t.request_key,'request_fingerprint',t.request_fingerprint) AS record FROM recurring_plan_versions t WHERE t.ledger_id IN(SELECT ledger_id FROM ledger_periods WHERE book_id=b.id) ORDER BY t.plan_id,t.version,t.ledger_id))),'recurring_plan_approvals',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('plan_id',t.plan_id,'version',t.version,'ledger_id',t.ledger_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'approved_by',t.approved_by,'reason',t.reason,'created_at',t.created_at) AS record FROM recurring_plan_approvals t WHERE t.ledger_id IN(SELECT ledger_id FROM ledger_periods WHERE book_id=b.id) ORDER BY t.plan_id,t.version,t.ledger_id))),'recurring_generations',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('plan_id',t.plan_id,'version',t.version,'ledger_id',t.ledger_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'period',t.period,'source_id',t.source_id,'draft_id',t.draft_id,'created_by',t.created_by,'created_at',t.created_at,'request_key',t.request_key,'request_fingerprint',t.request_fingerprint) AS record FROM recurring_generations t WHERE t.book_id=b.id ORDER BY t.plan_id,t.version,t.ledger_id))))) AS inputs_json FROM books b JOIN closing_fact_basis_stage16 v ON v.book_id=b.id;

CREATE VIEW closing_issue_rows_stage24 AS SELECT * FROM closing_issue_rows_stage16 UNION ALL SELECT c.book_id,'monthly_reference' AS category,'monthly_check' AS object_type,c.id AS object_id,'月度外部余额检查尚未人工核对，或依据已变化，须重新检查' AS detail FROM monthly_checks c
    WHERE c.version=(SELECT max(version) FROM monthly_checks WHERE book_id=c.book_id) AND (NOT EXISTS(SELECT 1 FROM monthly_check_closures x WHERE x.check_id=c.id) OR NOT(EXISTS(SELECT 1 FROM monthly_check_currentness n WHERE n.check_id=c.id AND n.is_current=1)) OR EXISTS(SELECT 1 FROM monthly_baselines o WHERE o.book_id=c.book_id AND o.kind='opening' AND o.version>(SELECT version FROM monthly_baselines WHERE id=c.opening_id)) OR EXISTS(SELECT 1 FROM monthly_baselines z WHERE z.book_id=c.book_id AND z.kind='closing' AND z.version>(SELECT version FROM monthly_baselines WHERE id=c.closing_id)))
    UNION ALL SELECT m.book_id,'monthly_reference','monthly_baseline',m.id,'月度外部余额尚未独立确认或未形成对应检查' FROM monthly_baselines m
    WHERE m.version=(SELECT max(version) FROM monthly_baselines WHERE book_id=m.book_id AND kind=m.kind) AND (NOT EXISTS(SELECT 1 FROM monthly_baseline_confirmations x WHERE x.baseline_id=m.id) OR NOT EXISTS(SELECT 1 FROM monthly_checks c WHERE c.book_id=m.book_id AND (c.opening_id=m.id OR c.closing_id=m.id)))
    UNION ALL SELECT b.id,'recurring_pending','recurring_plan',p.plan_id,'本月有已审批的固定事项计划尚未生成草稿，请核对实际发生情况' FROM recurring_plan_versions p JOIN recurring_plan_approvals a ON a.plan_id=p.plan_id AND a.version=p.version JOIN ledger_periods l ON l.ledger_id=p.ledger_id JOIN books b ON b.id=l.book_id
    WHERE p.version=(SELECT max(x.version) FROM recurring_plan_versions x JOIN recurring_plan_approvals reviewed ON reviewed.plan_id=x.plan_id AND reviewed.version=x.version WHERE x.plan_id=p.plan_id) AND b.period>=p.start_period AND (p.end_period IS NULL OR b.period<=p.end_period) AND NOT EXISTS(SELECT 1 FROM recurring_generations g WHERE g.plan_id=p.plan_id AND g.book_id=b.id);

CREATE VIEW service_material_currentness AS
 SELECT r.id AS request_id,CASE WHEN (SELECT state FROM material_request_actions WHERE request_id=r.id ORDER BY version DESC LIMIT 1)='accepted'
 AND NOT EXISTS(SELECT 1 FROM json_each((SELECT evidence_json FROM material_request_actions WHERE request_id=r.id AND action='submit' ORDER BY version DESC LIMIT 1)) stamp
 WHERE NOT EXISTS(SELECT 1 FROM business_events e WHERE e.id=json_extract(stamp.value,'$.event_id') AND coalesce(e.submitted_version,e.version)=json_extract(stamp.value,'$.event_version') AND e.fact_version=json_extract(stamp.value,'$.fact_version') AND e.firm_id=r.firm_id AND e.company_id=r.company_id AND e.applicant_id=r.assignee_user_id AND substr(json_extract(e.payload,'$.occurred_on'),1,7)=r.period)
 OR json_array_length(stamp.value,'$.attachments')<>(SELECT count(*) FROM business_attachments a WHERE a.event_id=json_extract(stamp.value,'$.event_id') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id))
 OR EXISTS(SELECT 1 FROM json_each(stamp.value,'$.attachments') entry WHERE NOT EXISTS(SELECT 1 FROM business_attachments a WHERE a.id=json_extract(entry.value,'$.id') AND a.event_id=json_extract(stamp.value,'$.event_id') AND a.sha256=json_extract(entry.value,'$.sha256') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id))))
 AND NOT EXISTS(SELECT 1 FROM json_each((SELECT attachment_evidence_json FROM material_request_actions WHERE request_id=r.id AND action='submit' ORDER BY version DESC LIMIT 1)) stamp WHERE NOT EXISTS(SELECT 1 FROM material_attachments a WHERE a.id=json_extract(stamp.value,'$.id') AND a.request_id=r.id AND a.sha256=json_extract(stamp.value,'$.sha256')))
 THEN 1 ELSE 0 END AS is_current FROM material_requests r;
DROP VIEW closing_issue_rows;
CREATE VIEW closing_issue_rows AS SELECT * FROM closing_issue_rows_stage24
 UNION ALL SELECT r.book_id,'required_material','material_request',r.id,'本月必交资料尚未独立验收，或已验收证据发生变化，请核对资料清单'
 FROM material_requests r JOIN service_material_currentness c ON c.request_id=r.id WHERE r.required=1 AND c.is_current=0;
DROP VIEW closing_fact_basis;
CREATE VIEW closing_fact_basis AS SELECT b.id AS book_id,json_patch(v.inputs_json,json_object('service_plan_versions',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'version',t.version,'lead_user_id',t.lead_user_id,'reviewer_user_id',t.reviewer_user_id,'backup_user_id',t.backup_user_id,'contact_user_id',t.contact_user_id,'due_on',t.due_on,'notes',t.notes,'reason',t.reason,'updated_by',t.updated_by,'updated_at',t.updated_at) AS record FROM service_plan_versions t WHERE t.book_id=b.id ORDER BY t.version))),'material_requests',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'period',t.period,'template_id',t.template_id,'item_key',t.item_key,'title',t.title,'description',t.description,'required',t.required,'due_on',t.due_on,'assignee_user_id',t.assignee_user_id,'created_by',t.created_by,'created_at',t.created_at) AS record FROM material_requests t WHERE t.book_id=b.id ORDER BY t.id))),'material_request_actions',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'request_id',t.request_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'version',t.version,'action',t.action,'state',t.state,'mode',t.mode,'reason',t.reason,'event_ids_json',t.event_ids_json,'evidence_json',t.evidence_json,'attachment_ids_json',t.attachment_ids_json,'attachment_evidence_json',t.attachment_evidence_json,'created_by',t.created_by,'created_at',t.created_at) AS record FROM material_request_actions t WHERE t.book_id=b.id ORDER BY t.id))),'material_attachments',json((SELECT coalesce(json_group_array(json(record)),'[]') FROM(SELECT json_object('id',t.id,'request_id',t.request_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'storage_key',t.storage_key,'filename',t.filename,'media_type',t.media_type,'sha256',t.sha256,'size_bytes',t.size_bytes,'created_by',t.created_by,'created_at',t.created_at) AS record FROM material_attachments t WHERE t.book_id=b.id ORDER BY t.id))))) AS inputs_json FROM books b JOIN closing_fact_basis_stage24 v ON v.book_id=b.id;
